from tornado.simple_httpclient import SimpleAsyncHTTPClient
from tornado.netutil import Resolver, OverrideResolver
from tornado.tcpclient import TCPClient

class TestSimpleAsyncHTTPClientInitialize(unittest.TestCase):
    def setUp(self):
        self.default_resolver = MagicMock(spec=Resolver)
        self.override_resolver = MagicMock(spec=OverrideResolver)
        self.tcp_client = MagicMock(spec=TCPClient)

    @patch('tornado.simple_httpclient.Resolver', return_value=MagicMock(spec=Resolver))
    @patch('tornado.simple_httpclient.OverrideResolver', return_value=MagicMock(spec=OverrideResolver))
    @patch('tornado.simple_httpclient.TCPClient', return_value=MagicMock(spec=TCPClient))
    def test_initialize_with_defaults(self, mock_tcp_client, mock_override_resolver, mock_resolver):
        client = SimpleAsyncHTTPClient()
        client.initialize()

        self.assertEqual(client.max_clients, 10)
        self.assertEqual(client.max_buffer_size, 104857600)
        self.assertIsNone(client.max_header_size)
        self.assertIsNone(client.max_body_size)
        self.assertTrue(client.own_resolver)
        self.assertIsInstance(client.resolver, Resolver)
        mock_tcp_client.assert_called_once_with(resolver=client.resolver)

    @patch('tornado.simple_httpclient.TCPClient', return_value=MagicMock(spec=TCPClient))
    def test_initialize_with_custom_resolver(self, mock_tcp_client):
        custom_resolver = MagicMock(spec=Resolver)
        client = SimpleAsyncHTTPClient()
        client.initialize(resolver=custom_resolver)

        self.assertEqual(client.resolver, custom_resolver)
        self.assertFalse(client.own_resolver)
        mock_tcp_client.assert_called_with(resolver=custom_resolver)

    @patch('tornado.simple_httpclient.Resolver', return_value=MagicMock(spec=Resolver))
    @patch('tornado.simple_httpclient.OverrideResolver', return_value=MagicMock(spec=OverrideResolver))
    @patch('tornado.simple_httpclient.TCPClient', return_value=MagicMock(spec=TCPClient))
    def test_initialize_with_hostname_mapping(self, mock_tcp_client, mock_override_resolver, mock_resolver):
        hostname_mapping = {'example.com': '127.0.0.1'}
        client = SimpleAsyncHTTPClient()
        client.initialize(hostname_mapping=hostname_mapping)

        mock_override_resolver.assert_called_once_with(resolver=mock_resolver.return_value, mapping=hostname_mapping)
        self.assertIsInstance(client.resolver, OverrideResolver)
        mock_tcp_client.assert_called_with(resolver=client.resolver)

    def test_initialize_with_custom_values(self):
        client = SimpleAsyncHTTPClient()
        client.initialize(max_clients=5, max_buffer_size=2048, max_header_size=512, max_body_size=1024)

        self.assertEqual(client.max_clients, 5)
        self.assertEqual(client.max_buffer_size, 2048)
        self.assertEqual(client.max_header_size, 512)
        self.assertEqual(client.max_body_size, 1024)

if __name__ == '__main__':
    unittest.main()

