from tornado.auth import OpenIdMixin

class TestOpenIdMixinGetAxArg(unittest.TestCase):
    def setUp(self):
        self.mixin = OpenIdMixin()
        self.handler = MagicMock()
        self.mixin.handler = self.handler

    @patch('tornado.auth.ax_ns', 'example_ns')
    def test_get_ax_arg_with_valid_uri(self):
        uri = "http://example.com/schema"
        self.handler.request.arguments = {
            "openid.example_ns.type.example": [uri],
            "openid.example_ns.value.example": ["value"]
        }
        self.handler.get_argument.side_effect = lambda name, default=None: self.handler.request.arguments.get(name, [default])[0]

        result = self.mixin.get_ax_arg(uri)
        self.assertEqual(result, "value")

    @patch('tornado.auth.ax_ns', 'example_ns')
    def test_get_ax_arg_with_invalid_uri(self):
        uri = "http://example.com/schema"
        self.handler.request.arguments = {
            "openid.example_ns.type.other": ["http://other.com/schema"],
            "openid.example_ns.value.other": ["value"]
        }
        self.handler.get_argument.side_effect = lambda name, default=None: self.handler.request.arguments.get(name, [default])[0]

        result = self.mixin.get_ax_arg(uri)
        self.assertEqual(result, "")

    @patch('tornado.auth.ax_ns', 'example_ns')
    def test_get_ax_arg_with_no_ax_ns(self):
        with patch('tornado.auth.ax_ns', None):
            uri = "http://example.com/schema"
            result = self.mixin.get_ax_arg(uri)
            self.assertEqual(result, "")

    @patch('tornado.auth.ax_ns', 'example_ns')
    def test_get_ax_arg_with_no_matching_prefix(self):
